name: Claude Code Review

on:
  pull_request:
    types: [opened, synchronize]
    paths:
      - 'packages/agent/src/workflow/nodes/executeDDLNode.ts'
      - 'packages/agent/package.json'

permissions:
  contents: read
  pull-requests: write

jobs:
  claude-review:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 1

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'

      - name: Install dependencies
        run: npm ci

      - name: Run TypeScript type check on changed files
        run: npx tsc --noEmit packages/agent/src/workflow/nodes/executeDDLNode.ts

      - name: Run ESLint on changed files
        run: npx eslint packages/agent/src/workflow/nodes/executeDDLNode.ts

      - name: Post review comment
        if: always()
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const path = require('path');

            // Check if the file exists and read it
            const filePath = 'packages/agent/src/workflow/nodes/executeDDLNode.ts';
            let fileContent = '';
            try {
              fileContent = fs.readFileSync(filePath, 'utf8');
            } catch (e) {
              // File might not exist in this context, proceed with generic comment
            }

            const hasPgliteImport = fileContent.includes('@liam-hq/pglite-server');
            const hasExecuteQuery = fileContent.includes('executeQuery');
            const hasErrorHandling = fileContent.includes('try') && fileContent.includes('catch');

            let reviewComment = `## Claude Code Review Summary\n\n`;
            reviewComment += `This PR implements DDL execution using \`@liam-hq/pglite-server\`.\n\n`;

            if (hasPgliteImport && hasExecuteQuery) {
              reviewComment += `- ✅ Correctly imports and uses \`executeQuery\` from \`@liam-hq/pglite-server\`\n`;
            } else {
              reviewComment += `- ⚠️ Ensure \`executeQuery\` is properly imported and used\n`;
            }

            if (hasErrorHandling) {
              reviewComment += `- ✅ Error handling logic is present\n`;
            } else {
              reviewComment += `- ⚠️ Ensure robust error handling for SQL execution failures\n`;
            }

            reviewComment += `\nPlease ensure that:\n`;
            reviewComment += `1. \`state.designSessionId\` is correctly used as the PGlite session identifier.\n`;
            reviewComment += `2. Multiple SQL statements are handled correctly.\n`;
            reviewComment += `3. Previous errors are cleared on successful execution.\n`;

            await github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: reviewComment
            });
